<div class="settings-grid"><?php foreach(['warehouses'=>[t('Warehouses'),$warehouses,t('Storage locations')],'rice_types'=>[t('Rice types'),$riceTypes,t('Your rice varieties')],'suppliers'=>[t('Suppliers'),$suppliers,t('Who you purchase from')]] as $type=>[$heading,$items,$subtitle]): ?><section class="panel"><div class="panel-heading"><div><div class="eyebrow"><?= e($subtitle) ?></div><h2><?= e($heading) ?></h2></div><span class="badge transfer"><?= count($items) ?></span></div>
<div class="settings-list"><?php foreach($items as $r): ?><div><strong><?= e($r['name']) ?></strong><small><?= e($r['location']??($r['phone']??'')) ?><?= isset($r['address'])?' · '.e($r['address']):'' ?></small></div><?php endforeach; ?><?php if(!$items): ?><p class="muted"><?= e(t('No {type} yet.',['type'=>$heading])) ?></p><?php endif; ?></div>
<form method="post" action="<?= e(url('settings')) ?>" class="stack setting-form"><?= csrf_field() ?><input type="hidden" name="type" value="<?= e($type) ?>"><?php field('name',t('Name'),'text','','required maxlength="120"'); if($type==='warehouses') field('location',t('Location'),'text','','maxlength="255"'); if($type==='suppliers') { field('phone',t('Phone'),'tel','','maxlength="50"'); field('address',t('Address'),'text','','maxlength="255"'); } ?><button class="button" type="submit"><?= e(t('＋ Add')) ?> <?= e(t(['warehouses'=>'warehouse','rice_types'=>'rice type','suppliers'=>'supplier'][$type])) ?></button></form></section><?php endforeach; ?></div>
